    /**
     * Tests getting all MedicalDevices.
     *
     * @return    Collection
     */
    public List<MedicalDevice> testGetAll() throws Throwable {
    LOGGER.info( "MedicalDeviceTest:testGetAll() - Retrieving Collection of MedicalDevices:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all MedicalDevice : " );
    List<MedicalDevice> collection  = null;

    try {
        // call the static get method on the MedicalDeviceService
        collection = service.getAllMedicalDevice();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            MedicalDevice currEntity  = null;
            Iterator<MedicalDevice> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getMedicalDeviceId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

